\documentclass[11pt,a4paper]{article}

% Package imports
\usepackage[margin=0.75in]{geometry}
\usepackage{hyperref}
\usepackage[utf8]{inputenc}
\usepackage{fontawesome}
\usepackage{titlesec}
\usepackage{enumitem}

% Custom commands and styling
\pagestyle{empty}
\titleformat{\section}{\Large\bfseries}{\thesection}{1em}{}[\titlerule]
\titlespacing*{\section}{0pt}{12pt}{8pt}

% Custom colors for hyperlinks
\hypersetup{
    colorlinks=true,
    urlcolor=blue,
    linkcolor=black
}

% Document begins
\begin{document}

% Header
\begin{center}
    {\Huge\textbf{Your Name}}\\[0.3cm]
    \faEnvelope\ email@example.com $\mid$ 
    \faPhone\ (123) 456-7890 $\mid$
    \faLinkedin\ \href{https://linkedin.com/in/yourprofile}{linkedin.com/in/yourprofile} $\mid$
    \faGithub\ \href{https://github.com/yourusername}{github.com/yourusername}
\end{center}

% Education Section
\section*{Education}
\textbf{University Name} \hfill \textit{Expected Graduation: Month Year}\\
Degree Name (e.g., Bachelor of Science in Computer Science)\\
GPA: X.XX/4.00
\vspace{0.5em}

% Experience Section
\section*{Experience}
\textbf{Company Name} \hfill \textit{Month Year -- Present}\\
\textit{Job Title}
\begin{itemize}[leftmargin=*]
    \item Accomplished [X] by implementing [Y], which led to [Z]
    \item Led a team of X people to deliver project ahead of schedule
    \item Improved efficiency by X\% through implementation of [process/tool]
\end{itemize}

\textbf{Previous Company} \hfill \textit{Month Year -- Month Year}\\
\textit{Job Title}
\begin{itemize}[leftmargin=*]
    \item Developed and maintained [specific project/system]
    \item Collaborated with cross-functional teams to achieve [specific goal]
    \item Reduced [metric] by X\% through [specific action]
\end{itemize}

% Projects Section
\section*{Projects}
\textbf{Project Name} \hfill \textit{Month Year}\\
\begin{itemize}[leftmargin=*]
    \item Built [what] using [technologies] that accomplished [result]
    \item Implemented [feature/algorithm] that improved [metric] by X\%
\end{itemize}

% Skills Section
\section*{Skills}
\textbf{Programming Languages:} Java, Python, C++, JavaScript\\
\textbf{Technologies:} React, Node.js, Git, Docker, AWS\\
\textbf{Other:} Agile Methodologies, Technical Writing, Team Leadership

% Awards & Certifications (Optional)
\section*{Awards \& Certifications}
\begin{itemize}[leftmargin=*]
    \item Certification Name (Authority Name) \hfill \textit{Month Year}
    \item Award/Honor Name \hfill \textit{Month Year}
\end{itemize}

\end{document}

